import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Define fused Linear+ReLU CUDA kernel
linear_relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void linear_relu_kernel(const float* x, const float* W, const float* b, float* out, 
                                   int batch_size, int in_features, int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_features;
    if (idx >= total_elements) return;

    int i = idx / out_features;
    int j = idx % out_features;

    float sum = 0.0f;
    for (int k = 0; k < in_features; ++k) {
        sum += x[i * in_features + k] * W[j * in_features + k];
    }
    sum += b[j];
    out[idx] = fmaxf(sum, 0.0f);
}

torch::Tensor fused_linear_relu_cuda(torch::Tensor x, torch::Tensor W, torch::Tensor b) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = W.size(0);

    auto out = torch::empty({batch_size, out_features}, x.options());

    int total_elements = batch_size * out_features;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    linear_relu_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        W.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

linear_relu_cpp_source = "torch::Tensor fused_linear_relu_cuda(torch::Tensor x, torch::Tensor W, torch::Tensor b);"

fused_linear_relu = load_inline(
    name='fused_linear_relu',
    cpp_sources=linear_relu_cpp_source,
    cuda_sources=linear_relu_source,
    functions=['fused_linear_relu_cuda'],
    verbose=True
)

class FusedLinearReLU(nn.Module):
    def __init__(self, input_size, output_size):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(output_size, input_size))
        self.bias = nn.Parameter(torch.Tensor(output_size))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_linear_relu.fused_linear_relu_cuda(x, self.weight, self.bias)

class ModelNew(nn.Module):
    def __init__(self, input_size, layer_sizes, output_size):
        super(ModelNew, self).__init__()
        layers = []
        current_input_size = input_size
        for layer_size in layer_sizes:
            layers.append(FusedLinearReLU(current_input_size, layer_size))
            current_input_size = layer_size
        layers.append(nn.Linear(current_input_size, output_size))
        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)
